SELECT rating_bucket, rating_count, stddev_rating FROM (SELECT CASE WHEN rating >= 4.0 THEN 'high' WHEN rating >= 2.6 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(rating) AS rating_count, ROUND(STDDEV(rating), 2) AS stddev_rating FROM suppliers WHERE UPPER(supplier_name) LIKE '%URO%' GROUP BY CASE WHEN rating >= 4.0 THEN 'high' WHEN rating >= 2.6 THEN 'mid' ELSE 'low' END) AS s WHERE rating_count < 9;
